// ASSIGN OWNER
// Picks who handles this lead and writes the internal email.

// ---------- SETTINGS (change names and emails here) ----------
const TEAM = {
  founder: { name: 'Founder', email: 'founder@example.com' },
  pro:     { name: 'Pro Artist Team', email: 'pro@example.com' },
  ops:     { name: 'Operations', email: 'ops@example.com' },
  reps: [
    { name: 'Wholesale Rep 1', email: 'rep1@example.com' },
    { name: 'Wholesale Rep 2', email: 'rep2@example.com' },
  ],
};
const TEAM_INBOX = 'team@example.com';   // CC'd on every internal email
const RESPONSE_MINUTES = 60;
// --------------------------------------------------------------

const lead = $json;
const rows = $('Dupe look up').all().map(i => i.json).filter(r => r.lead_id);
const count = rep => rows.filter(r => r.owner_email === rep.email).length;

// Who owns it:
// C -> Pro team, Review -> Operations, D -> nobody.
// A/B -> founder for distributors and $5000+ orders,
//        otherwise keep their old rep, or give it to the rep with the fewest leads.
let owner = null;
if (lead.tier === 'C') owner = TEAM.pro;
else if (lead.tier === 'REVIEW') owner = TEAM.ops;
else if (lead.tier === 'A' || lead.tier === 'B') {
  if (lead['Business Type'] === 'Distributor' || lead['Estimated First Order'] === '$5000+') owner = TEAM.founder;
  else owner = TEAM.reps.find(r => r.email === lead.prev_owner_email)
    || TEAM.reps.reduce((least, rep) => (count(rep) < count(least) ? rep : least));
}

const changed = lead.is_update && lead.prev_tier && lead.prev_tier !== lead.tier;
const STATUS = { A: 'Awaiting first contact', B: 'Awaiting first contact', C: 'Sent to Pro team', D: 'Declined', REVIEW: 'Needs review' };
const urgent = ['A', 'B', 'C'].includes(lead.tier);

const ownerBody = [
  urgent ? `Please reach out within ${RESPONSE_MINUTES} minutes.` : 'Please review this lead.',
  changed ? `Status changed from ${lead.prev_tier} to ${lead.tier}.` : null,
  '',
  `Lead ID: ${lead.lead_id}${lead.is_update ? ' (returning lead)' : ''}`,
  `Tier: ${lead.tier} (${lead.track})`,
  `Business: ${lead['Business Name']} | ${lead['Business Type']}`,
  `Contact: ${lead['Contact Name']} | ${lead['Email']} | ${lead['Phone'] || 'no phone'}`,
  `Location: ${lead['City/State']}, ${lead['Country']}`,
  `First order: ${lead['Estimated First Order']} | Resale certificate: ${lead['Resale Certificate']}`,
  `Website or social: ${lead['Website or Social Media']}`,
  lead['Notes'] ? `Applicant notes: ${lead['Notes']}` : null,
].filter(v => v !== null).join('\n');

return { json: {
  ...lead,
  submitted_at: lead.first_submitted_at,
  updated_at: new Date().toISOString(),
  owner_name: owner ? owner.name : '',
  owner_email: owner ? owner.email : '',
  status: STATUS[lead.tier],
  contact_due_by: urgent ? new Date(Date.now() + RESPONSE_MINUTES * 60000).toISOString() : '',
  email_subject: changed && ['A', 'B'].includes(lead.tier) ? 'Good news about your Acme application' : lead.email_subject,
  email_body: (lead.email_body || '').replace('[OWNER]', owner ? owner.name : 'Our team'),
  notify_owner: lead.tier !== 'D',
  team_inbox: TEAM_INBOX,
  owner_subject: `[${lead.tier}] ${lead['Business Name']} - ${lead.lead_id}${changed ? ' (status changed)' : ''}`,
  owner_body: ownerBody,
}};

// FIND MATCH
// Checks if this lead already exists in the Leads sheet,
// then gives it a Lead ID (reuses the old one, or makes the next number).

const lead = $('Cleaning').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.lead_id);
const digits = v => String(v ?? '').replace(/\D/g, '');
const email = String(lead['Email'] ?? '').toLowerCase();
const phone = digits(lead['Phone']);

// Duplicate check: same email first, then same phone number
const byEmail = rows.find(r => String(r['Email'] ?? '').toLowerCase() === email);
const byPhone = phone.length >= 7 ? rows.find(r => digits(r['Phone']) === phone) : null;
const existing = byEmail || byPhone;

// Highest Lead ID number so far (Acme-0007 -> 7)
const maxId = Math.max(0, ...rows.map(r => parseInt(digits(r.lead_id), 10) || 0));

return [{ json: {
  ...lead,
  lead_id: existing ? existing.lead_id : 'Acme-' + String(maxId + 1).padStart(4, '0'),
  is_update: !!existing,
  prev_tier: existing ? existing.tier : '',
  prev_owner_email: existing ? existing.owner_email : '',
  first_submitted_at: existing ? existing.submitted_at : new Date().toISOString(),
  conflict: !!(byEmail && byPhone && byEmail.lead_id !== byPhone.lead_id),
}}];
